//!       in implied_end_thorough
//!   foreign: image math svg
//!       in special, formatting, scope, list_item_scope, button_scope, table_scope, select_scope,
//!       implied_end, implied_end_thorough, void, data mode
//!   popped: applet marquee object select template
//!       in formatting
//!   text: iframe noembed noframes noscript plaintext script style textarea title xmp
//!       in special, formatting, scope, list_item_scope, button_scope, table_scope, select_scope,
//!       implied_end, implied_end_thorough
//!   thorough: caption colgroup tbody td tfoot th thead tr
//!       in implied_end_thorough
//!   void: area base basefont bgsound br col embed frame hr img input keygen link meta param source
//!   track wbr
//!       in special, formatting, scope, list_item_scope, button_scope, table_scope, select_scope,
//!       implied_end, implied_end_thorough

use crate::tokenizer::DataMode;

pub(crate) const SPECIAL: u16 = 1 << 0;
pub(crate) const FORMATTING: u16 = 1 << 1;
pub(crate) const SCOPE: u16 = 1 << 2;
pub(crate) const LIST_ITEM_SCOPE: u16 = 1 << 3;
pub(crate) const BUTTON_SCOPE: u16 = 1 << 4;
pub(crate) const TABLE_SCOPE: u16 = 1 << 5;
pub(crate) const SELECT_SCOPE: u16 = 1 << 6;
pub(crate) const IMPLIED_END: u16 = 1 << 7;
pub(crate) const IMPLIED_END_THOROUGH: u16 = 1 << 8;
pub(crate) const VOID: u16 = 1 << 9;

/// The category flags of an HTML-namespace element name (ASCII lowercase), OR-ed together.
pub(crate) fn html5_cat(name: &[u8]) -> u16 {
    match name {
        b"address" | b"article" | b"aside" | b"blockquote" | b"body" | b"center" | b"details" |
        b"dir" | b"div" | b"dl" | b"fieldset" | b"figcaption" | b"figure" | b"footer" | b"form" |
        b"frameset" | b"h1" | b"h2" | b"h3" | b"h4" | b"h5" | b"h6" | b"head" | b"header" |
        b"hgroup" | b"iframe" | b"listing" | b"main" | b"menu" | b"nav" | b"noembed" |
        b"noframes" | b"noscript" | b"plaintext" | b"pre" | b"script" | b"section" | b"style" |
        b"summary" | b"textarea" | b"title" | b"xmp" => {
            SPECIAL
        }
        b"a" | b"b" | b"big" | b"code" | b"em" | b"font" | b"i" | b"nobr" | b"s" | b"small" |
        b"strike" | b"strong" | b"tt" | b"u" => {
            FORMATTING
        }
        b"ol" | b"ul" => SPECIAL | LIST_ITEM_SCOPE,
        b"button" => SPECIAL | BUTTON_SCOPE,
        b"colgroup" | b"tbody" | b"tfoot" | b"thead" | b"tr" => SPECIAL | IMPLIED_END_THOROUGH,
        b"optgroup" | b"option" | b"rb" | b"rp" | b"rt" | b"rtc" => {
            IMPLIED_END | IMPLIED_END_THOROUGH
        }
        b"area" | b"base" | b"basefont" | b"bgsound" | b"br" | b"col" | b"embed" | b"frame" |
        b"hr" | b"img" | b"input" | b"keygen" | b"link" | b"meta" | b"param" | b"source" |
        b"track" | b"wbr" => {
            SPECIAL | VOID
        }
        b"dd" | b"dt" | b"li" | b"p" => SPECIAL | IMPLIED_END | IMPLIED_END_THOROUGH,
        b"applet" | b"marquee" | b"object" | b"select" => {
            SPECIAL | SCOPE | LIST_ITEM_SCOPE | BUTTON_SCOPE | SELECT_SCOPE
        }
        b"html" | b"table" | b"template" => {
            SPECIAL | SCOPE | LIST_ITEM_SCOPE | BUTTON_SCOPE | TABLE_SCOPE | SELECT_SCOPE
        }
        b"caption" | b"td" | b"th" => {
            SPECIAL | SCOPE | LIST_ITEM_SCOPE | BUTTON_SCOPE | SELECT_SCOPE | IMPLIED_END_THOROUGH
        }
        _ => 0,
    }
}

/// How the tokenizer reads the content of an HTML-namespace element, with scripting on.
/// `script` is raw text here; its escape states are the tokenizer's, keyed on the name.
pub(crate) fn html5_data_mode(name: &[u8]) -> DataMode {
    match name {
        b"iframe" | b"noembed" | b"noframes" | b"noscript" | b"script" | b"style" | b"xmp" => {
            DataMode::Rawtext
        }
        b"textarea" | b"title" => DataMode::Rcdata,
        b"plaintext" => DataMode::Plaintext,
        _ => DataMode::Normal,
    }
}
